#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *file = fopen(argv[1], "r");
    if (file == NULL) {
        printf("Could not open file %s\n", argv[1]);
        return 1;
    }

    int adj[8][8] = {{0}};
    int indegree[8] = {0};
    int done[8] = {0};
    int queue[8];
    int front = 0, rear = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        int u, v;
        sscanf(line, "%d %d", &u, &v);
        adj[u][v] = 1;
        indegree[v]++;
    }

    fclose(file);

    for (int i = 0; i < 8; i++) {
        if (indegree[i] == 0) {
            queue[rear++] = i;
        }
    }

    while (front < rear) {
        int u = queue[front++];
        printf("%d ", u);
        done[u] = 1;

        for (int v = 0; v < 8; v++) {
            if (adj[u][v] && !done[v]) {
                indegree[v]--;
                if (indegree[v] == 0) {
                    queue[rear++] = v;
                }
            }
        }
    }

    printf("\n");

    for (int i = 0; i < 8; i++) {
        if (!done[i]) {
            printf("CYCLE\n");
            return 1;
        }
    }

    return 0;
}
